class Row:
    source_period: int
    observed_period: int
    fiber_size: int

def divisor_cycle_table(n: int) -> list[Row]:
    if n < 1:
        raise ValueError("n must be positive")
    return [Row(n, d, n // d) for d in range(1, n + 1) if n % d == 0]

if __name__ == "__main__":
    for row in divisor_cycle_table(12):
        print(row)

from __future__ import annotations
from math import isqrt

def is_prime(n: int) -> bool:
    return n >= 2 and all(n % k for k in range(2, isqrt(n) + 1))

def possible_observed_periods(n: int) -> list[int]:
    return [d for d in range(1, n + 1) if n % d == 0]

if __name__ == "__main__":
    for p in (2, 3, 5, 7, 11, 13):
        assert is_prime(p)
        print(p, possible_observed_periods(p))

from __future__ import annotations
from typing import Callable

def period(step: Callable[[int], int], start: int, bound: int) -> int:
    state = start
    for k in range(1, bound + 1):
        state = step(state)
        if state == start:
            return k
    raise ValueError("no return found")

def faithful_relabeling(n: int) -> tuple[int, int]:
    labels = [n - 1 - x for x in range(n)]
    inverse = {label: x for x, label in enumerate(labels)}
    f = lambda x: (x + 1) % n
    g = lambda y: labels[(inverse[y] + 1) % n]
    return period(f, 0, n), period(g, labels[0], n)

if __name__ == "__main__":
    for n in range(2, 11):
        hidden, observed = faithful_relabeling(n)
        assert hidden == observed == n
        print(n, hidden, observed)

