from __future__ import annotations
from typing import Sequence

def audit_semiconjugacy(f: Sequence[int], g: Sequence[int], h: Sequence[int]) -> bool:
    if len(h) != len(f):
        raise ValueError("h must label every source state")
    return all(h[f[x]] == g[h[x]] for x in range(len(f)))

from __future__ import annotations
from typing import Sequence

def minimal_period(successor: Sequence[int], start: int) -> int | None:
    first_seen: dict[int, int] = {start: 0}
    state = start
    for time in range(1, len(successor) + 1):
        state = successor[state]
        if state == start:
            return time
        if state in first_seen:
            return None
        first_seen[state] = time
    return None

from __future__ import annotations
from dataclasses import dataclass
from typing import Sequence

@dataclass(frozen=True)
class Audit:
    hidden: int
    observed: int
    valid: bool

def period(step: Sequence[int], start: int) -> int:
    state = start
    for k in range(1, len(step) + 1):
        state = step[state]
        if state == start:
            return k
    raise ValueError("start is not periodic")

def transport_audit(f: Sequence[int], g: Sequence[int], h: Sequence[int], x: int) -> Audit:
    if any(h[f[s]] != g[h[s]] for s in range(len(f))):
        raise ValueError("observation does not commute with evolution")
    n, d = period(f, x), period(g, h[x])
    return Audit(n, d, n % d == 0)

